private function raw_body( WP_REST_Request $request ): string {
    $raw = $request->get_body();
    if ( null === $raw || '' === $raw ) {
        $raw = WP_REST_Server::get_raw_data();          // cached global, no stream re-read
    }
    if ( null === $raw || '' === $raw ) {
        $raw = file_get_contents( 'php://input' );      // last resort only
    }
    $raw = (string) $raw;
    // Fail closed. An empty body is never 'no signature needed'.
    // (Also: if the body exceeded PHP post_max_size, $raw is '' here.)
    return $raw;
}

// In verify(): hash $raw. In handle(): use $request->get_json_params()
// (it parses the SAME $this->body you just signed) or json_decode( $raw, true ).
// Never json_decode( file_get_contents('php://input') ) in the handler.

