// Always hash the attacker-controlled Request-Id into a fixed-length key.
$rid = (string) $request->get_header( 'x-webhook-request-id' );
if ( '' === $rid ) { return $this->deny(); }
$key = 'apollo_wa_hook_' . hash( 'sha256', $rid );   // 15 + 64 = 79 chars, safely < 172

// Option A (simple, good enough): accept the narrow race, make handlers idempotent.
// The SSOT already requires idempotent handlers for the 500-retry case.
if ( false !== get_transient( $key ) ) {
    return new WP_REST_Response( null, 200 );        // 200 with empty body; see topic 5 note
}
set_transient( $key, 1, 10 * MINUTE_IN_SECONDS );    // set BEFORE the slow work

// Option B (truly atomic, if duplicate processing is unacceptable).
// Own option pair, NOT the transient API - do not mix with get_transient().
global $wpdb;
$lock = 'apollo_wa_hook_lock_' . hash( 'sha256', $rid );
$won  = (bool) $wpdb->query( $wpdb->prepare(
    "INSERT IGNORE INTO `{$wpdb->options}` (`option_name`,`option_value`,`autoload`) VALUES (%s,%s,'off')",
    $lock,
    (string) time()
) );
wp_cache_delete( $lock, 'options' );
wp_cache_delete( 'notoptions', 'options' );
if ( ! $won ) { return new WP_REST_Response( null, 200 ); }   // duplicate delivery
// ...and reap rows older than 10 min on a scheduled event.

