private function transport_ok(): bool {
    // 1. Site configuration - not request data, cannot be spoofed by a caller.
    $site_https = 'https' === strtolower( (string) wp_parse_url( home_url(), PHP_URL_SCHEME ) );

    // 2. Request-level signals, used only to WIDEN, never to deny.
    $req_https = is_ssl();
    if ( ! $req_https && ! empty( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) ) {
        $xfp = strtolower( trim( explode( ',', wp_unslash( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) )[0] ) );
        $req_https = ( 'https' === $xfp );
    }

    $env = wp_get_environment_type();   // 'production' on LocalWP unless configured
    if ( 'local' === $env || 'development' === $env ) {
        return true;                    // lab: allow plain http
    }

    // Production: require the SITE to be https. Do not hard-fail on is_ssl()
    // alone, or every TLS-terminating proxy deployment 401s forever.
    return $site_https || $req_https;
}

