public function verify( WP_REST_Request $request ) {
    // Single exit discipline: only ever `return true;` or `return WP_Error`.
    // Never return an int, a count, a string, or a bare false.
    try {
        if ( ! $this->transport_ok() )        { return $this->deny(); }
        $raw = $this->raw_body( $request );
        if ( '' === $raw )                    { return $this->deny(); }
        if ( strlen( $raw ) > 256 * KB_IN_BYTES ) { return $this->too_large(); }
        $key = (string) get_option( 'apollo_wa_hmac_key', '' );
        if ( strlen( $key ) < 32 )            { return $this->deny(); }  // see 7c
        // ... header + hmac + timestamp checks, each `return $this->deny();`
        return true;                          // strictly true, nothing else
    } catch ( \Throwable $e ) {
        // Core does not catch. An uncaught throw here is a 500, not a 401.
        return $this->deny();
    }
}

